    // AK 不再加载外部贴图（之前用用户上传的 UV 展开图有严重错乱），改用程序化暖木纹/深橄榄金属 diffuse 严格匹配用户 3D 渲染图主色

    // 两把枪各自独立的高精度模型，切换时显隐
    this._viewGuns = {
      usp: this._buildUSP(uspMat, uspDarkMat, uspGripMat),
      ak47: this._buildAK(akAk47WarmMat, woodMat, akAk47Mat, akAk47DarkMat),
      awp: this._buildAwp(akAk47WarmMat, woodMat, akAk47Mat, akAk47DarkMat),
    };
    this._viewGroup.add(this._viewGuns.usp);
    this._viewGroup.add(this._viewGuns.ak47);
    this._viewGroup.add(this._viewGuns.awp);

    // 记录材质映射，供贴图懒加载完成后重新应用（QA#2）
    this._texMats = {
      usp: [uspMat, uspDarkMat, uspGripMat],
      ak47: [akAk47Mat, akAk47WarmMat, akAk47DarkMat],
    };

    // 当前枪模姿态
    this._viewRecoil = 0;

